class Solution:
    def findMaxConsecutiveOnes(self, nums: List[int]) -> int:
        n = len(nums)
        best = 0
        curr = 0

        for i in range(n):
            if nums[i] == 1:
                curr += 1
                best = max(best, curr)
            else:
                curr = 0
        return best
